// Quantities are teaspoons for two people. Ratios show the first three ingredients.
function saucesFor(cuisine, color, rows) {
  return rows.map(([id,name,use,time,desc,items,method,swap,recipe]) => ({
    id,name,use,time,desc,items,method,swap,recipe,cuisine,color,
    ratio:items.slice(0,3).map(([label,amount]) => amount + " " + label.toLowerCase()).join(" · ")
  }));
}

